T = 170.0; N = int(T * SR); STEMS = {}
def stem(name): return STEMS.setdefault(name, np.zeros((N, 2), np.float32))
def add(name, x, t=0., g=1.): put(stem(name), x, t, g)
def gain(pts): return curve(pts, N)[:, None]
def trk(sf2, prog=0, bank=0): return S.Track(sf2, prog, bank)
def ren(name, tr, g=1., width=None, p=0.):
    x = tr.render(T)
    if width is not None: # widen a mono-ish sample: decorrelate with a short delay pair
        m = x.mean(1); d = int(.011 * SR); e = np.concatenate([np.zeros(d, np.float32), m[:-d]]); x = np.stack([m * (1 - width * .5) + e * width * .5 * .0 + m * width * .0, m], 1); x = np.stack([.5 * (1 + width) * m - .0 * e, .5 * (1 + width) * (m * (1 - width) + e * width)], 1)
    if p: l, r = np.cos((p + 1) * np.pi / 4) * 1.414, np.sin((p + 1) * np.pi / 4) * 1.414; x = x * np.array([l, r], np.float32)
    add(name, x, 0, g); return x
