def zh(notes, g=.6, seed=100, dur=5.):
    for i, (t, n, v) in enumerate(notes): x = bell('zhong', hz(n), dur, v, seed + i); p = ((i * 37) % 11 - 5) / 7.; x = x * np.array([1 - max(0, p) * .7, 1 + min(0, p) * .7], np.float32); add('zhong', x, t, g)
def qi(notes, g=.5, seed=300, dur=4., long=1.):
    for i, (t, n, v) in enumerate(notes): x = bell('qing', hz(n), dur, v, seed + i, long=long); p = ((i * 53) % 13 - 6) / 8.; x = x * np.array([1 - max(0, p) * .7, 1 + min(0, p) * .7], np.float32); add('zhong', x, t, g)
