def swell(t0, t1, seed=1, g=1.): # a metal roll growing out of nothing
    n = int((t1 - t0) * SR); t = np.linspace(0, 1, n); x = np.zeros((n, 2), np.float32)
    for c in range(2): q = noise(n, seed * 7 + c); x[:, c] = (.6 * bp(q, 300, 1600) + .9 * bp(q, 2200, 9000) * t) * (t ** 2.8) * (.8 + .2 * slow(n, 13, seed + c))
    x[-int(.02 * SR):] *= np.linspace(1, 0, int(.02 * SR))[:, None]; add('gong', x, t0, .20 * g)
