def doors(t0=37.4, t1=45.0): # bronze and stone: rumble plus slow stick-slip, following the speed of the leaves
    n = int((t1 - t0 + .6) * SR); t = np.arange(n) / SR; q = np.clip(t / (t1 - t0), 0, 1); p = 2.2; ei = np.where(q < .5, .5 * (2 * q) ** p, 1 - .5 * (2 - 2 * q) ** p); sp = np.gradient(ei) * SR; sp = sp / sp.max(); env = np.clip(sp, 0, 1) ** .8 * np.clip(t / .5, 0, 1) * np.clip((t1 - t0 + .5 - t) / .5, 0, 1); out = np.zeros((n, 2), np.float32)
    for c in range(2): b = lp(noise(n, 70 + c), 110, 3) * 3.2 + .5 * bp(noise(n, 80 + c), 60, 240); out[:, c] = b * env * (.8 + .2 * slow(n, 9, 85 + c))
    rate = 7 + 16 * env; ph = np.cumsum(rate / SR) + .25 * slow(n, 5, 91); imp = (np.diff(np.floor(ph), prepend=0) > 0).astype(np.float32) * rng(4).uniform(.3, 1, n).astype(np.float32); cr = np.zeros(n, np.float32)
    for f, qq, g in [(92, 14, 1.), (143, 18, .8), (231, 22, .55), (377, 26, .35), (612, 24, .20), (930, 20, .10)]: cr += svf(imp, f * (1 + .03 * slow(n, 1.2, int(f))), qq, 1) * g
    cr = cr * env * 1.2; out += pan(cr, .2 * slow(n, .5, 99)); add('sfx', out, t0, .42)
