def growl(t0, d, seed=0, g=1.): n = int(d * SR); t = np.linspace(0, 1, n); e = np.sin(np.pi * t) ** 1.2; src = signal.sawtooth(2 * np.pi * np.cumsum(38 + 10 * np.sin(np.pi * t) + 2 * slow(n, 17, seed)) / SR).astype(np.float32) * .5 + noise(n, seed) * .5; am = .6 + .4 * np.sin(2 * np.pi * np.cumsum(23 + 4 * slow(n, 3, seed + 1)) / SR); x = sum(svf(src * am, f * (1 + .15 * np.sin(np.pi * t)), q) * a for f, q, a in [(105, 5, 1.), (240, 6, .7), (520, 7, .35), (1100, 6, .12)]); add('sfx', pan((x * e * .10).astype(np.float32), .1), t0, g)
